mapper.select:
		SELECT COUNT(*)
          FROM FTA_INCOTERMS_INFO A
         WHERE A.COMPANY_CODE = #{company_code}
           AND A.STD_YYYY = #{std_yyyy}
           AND A.DIVISION_CODE = #{division_code}
           AND A.INCOTERMS_TYPE = #{incoterms_type}
           AND A.NATION_CODE = #{nation_code}

mapper.update:
		UPDATE FTA_INCOTERMS_INFO
		   SET EXW_RATE =  #{exw_rate}                  
            , FCA_RATE =  #{fca_rate}                 
            , FAS_RATE =  #{fas_rate}                  
            , FOB_RATE =  #{fob_rate}                  
            , CFR_RATE =  #{cfr_rate}                 
            , CIF_RATE =  #{cif_rate}               
            , CPT_RATE =  #{cpt_rate}                 
            , CIP_RATE =  #{cip_rate}              
            , DAP_RATE =  #{dap_rate}
            , DPU_RATE =  #{dpu_rate}               
            , DDP_RATE =  #{ddp_rate} 
            , UPDATE_DATE = NOW()
       	 , UPDATE_BY = #{update_by}
        WHERE COMPANY_CODE = #{company_code}
          AND STD_YYYY = #{std_yyyy}
          AND DIVISION_CODE = #{division_code}
          AND INCOTERMS_TYPE = #{incoterms_type}
          AND NATION_CODE = #{nation_code}

mapper.delete:
		DELETE FROM FTA_INCOTERMS_INFO
		WHERE COMPANY_CODE = #{company_code}
         AND STD_YYYY = #{std_yyyy}
         AND DIVISION_CODE = #{division_code}
         AND INCOTERMS_TYPE = #{incoterms_type}
         AND NATION_CODE = #{nation_code}
